SELECT bno, title, content, writer, regdate, updatedate, replycnt, username
FROM (
    SELECT /*+ INDEX_DESC(b pk_board) */
           ROWNUM rn, b.bno, b.title, b.content, b.writer, b.regdate, b.updatedate, b.replycnt, m.username
    FROM tbl_board b
    LEFT JOIN tbl_member m ON b.writer = m.userid
    WHERE 





        ROWNUM <= #{pageNum} * #{amount}
)
WHERE rn > (#{pageNum} - 1) * #{amount}

mapper.update:
UPDATE tbl_board
SET replycnt = replycnt + #{amount}
WHERE bno = #{bno}
